383		// 把时钟拨回版本登记之前，查询结论也不变。
384		setNow(time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC))
385		got, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 10, 12, 0, 0, 0, time.UTC))
386		if err != nil || got.VersionID != "seat-v2" {
387			t.Fatalf("时钟在过去不影响查未来: %+v (%v)", got, err)
388		}
389	}
390	
391	// 后来补登过去生效的替代版本后，历史时刻按账本当前登记的实际区间回答：
392	// 选择依据是“查询时”已经登记的实际有效区间，而不是该时刻当时已知的版本。
393	func TestEffectiveVersionAtReflectsRetroactiveRegistration(t *testing.T) {
394		now, _ := fixedClock(time.Date(2026, 3, 15, 10, 0, 0, 0, time.UTC))
395		b := NewBook(WithClock(now))
396		oldEnd := time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
397		if err := b.RegisterVersion(RegisterRequest{
398			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
399			Start: effV1Start, End: &oldEnd,
400		}); err != nil {
401			t.Fatal(err)
402		}
403		// 补登前：3 月 15 日只有旧版。
404		got, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC))
405		if err != nil || got.VersionID != "seat-v1" {
406			t.Fatalf("补登前 3 月 15 日应选旧版: %+v (%v)", got, err)
407		}
408	
409		// 在 3 月 15 日补登 3 月 10 日起生效的替代版本。
410		if err := b.RegisterVersion(RegisterRequest{
411			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
412			Start: effV2Start, Replaces: "seat-v1",
413		}); err != nil {
414			t.Fatal(err)
415		}
416		// 补登后再查同一历史时刻：旧版实际区间已被截断到 3 月 10 日，应选新版。
417		got, err = b.EffectiveVersionAt("seat", time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC))
418		if err != nil || got.VersionID != "seat-v2" {
419			t.Fatalf("补登后历史时刻应按当前登记的实际区间选新版: %+v (%v)", got, err)
420		}
421		got, err = b.EffectiveVersionAt("seat", time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC))
422		if err != nil || got.VersionID != "seat-v1" {
423			t.Fatalf("交接点之前仍应选旧版: %+v (%v)", got, err)
424		}
425	}
426	
427	// 返回结果沿用版本视图的全部信息：版本标识、整数分单价、登记起止、
428	// 实际有效区间与双向替代关系，供调用方核对选择依据。
429	func TestEffectiveVersionAtViewFields(t *testing.T) {
430		b, _ := newEffectiveVersionBook(t, effV1Start)
431	
432		old, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC))
433		if err != nil {
434			t.Fatal(err)
435		}
436		if old.ItemID != "seat" || old.VersionID != "seat-v1" || old.UnitPrice != 150 {
437			t.Fatalf("旧版标识/单价异常: %+v", old)
438		}
439		if !old.Start.Equal(effV1Start) || !old.EffectiveStart.Equal(effV1Start) {
440			t.Fatalf("旧版开始时刻异常: %+v", old)
441		}
442		if old.End == nil || !old.End.Equal(effV1End) {
443			t.Fatalf("旧版应保留登记结束 3 月 31 日: %v", old.End)
444		}
445		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(effV2Start) {
446			t.Fatalf("旧版实际结束应显示交接点 3 月 10 日: %v", old.EffectiveEnd)
447		}
448		if old.Replaces != "" || old.SupersededBy != "seat-v2" {
449			t.Fatalf("旧版替代关系异常: Replaces=%q SupersededBy=%q", old.Replaces, old.SupersededBy)
450		}
451	
452		nv, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC))
453		if err != nil {
454			t.Fatal(err)
455		}
456		if nv.ItemID != "seat" || nv.VersionID != "seat-v2" || nv.UnitPrice != 180 {
457			t.Fatalf("新版标识/单价异常: %+v", nv)
458		}
459		if !nv.Start.Equal(effV2Start) || !nv.EffectiveStart.Equal(effV2Start) {
460			t.Fatalf("新版开始时刻异常: %+v", nv)
461		}
462		if nv.End == nil || !nv.End.Equal(effV2End) {
463			t.Fatalf("新版登记结束异常: %v", nv.End)
464		}
465		if nv.EffectiveEnd == nil || !nv.EffectiveEnd.Equal(effV2End) {
466			t.Fatalf("新版实际结束异常: %v", nv.EffectiveEnd)
467		}
468		if nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
469			t.Fatalf("新版替代关系异常: Replaces=%q SupersededBy=%q", nv.Replaces, nv.SupersededBy)
470		}
471	}
472	
473	// 查询结果是独立副本：修改返回的结束时间不能改变账本、其他查询结果或后续报价。
474	func TestEffectiveVersionAtViewMutationIsolated(t *testing.T) {
475		b, setNow := newEffectiveVersionBook(t, effV1Start)
476	
477		old, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC))
478		if err != nil {
479			t.Fatal(err)
480		}
481		// 调用方为展示目的改写这份结果中的两种结束时间。
482		*old.End = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
483		*old.EffectiveEnd = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
484	
485		again, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC))
486		if err != nil {
487			t.Fatal(err)
488		}
489		if again.End == nil || !again.End.Equal(effV1End) {
490			t.Fatalf("登记结束被查询结果的修改改写: %v", again.End)
491		}
492		if again.EffectiveEnd == nil || !again.EffectiveEnd.Equal(effV2Start) {
493			t.Fatalf("实际结束被查询结果的修改改写: %v", again.EffectiveEnd)
494		}
495	
496		// 两次查询的同名指针字段也必须互相独立。
497		if old.End == again.End || old.EffectiveEnd == again.EffectiveEnd {
498			t.Fatal("两次生效版本查询共享了结束时间指针")
499		}
500		views, err := b.ItemVersions("seat")
501		if err != nil {
502			t.Fatal(err)
503		}
504		for _, v := range views {
505			if v.VersionID == "seat-v1" {
506				if v.End == again.End || v.EffectiveEnd == again.EffectiveEnd {
507					t.Fatal("生效版本查询与版本列表查询共享了结束时间指针")
508				}
509			}
510		}
511	
512		// 报价仍按账本真实区间处理：交接点起旧版失效、新版有效。
513		setNow(effV2Start)
514		out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "seat-v1", Quantity: 1})
515		if out.Confirmed || out.Reason != ReasonVersionExpired {
516			t.Fatalf("修改查询结果不能影响后续报价依据: %+v", out)
517		}
518		out, _ = b.Quote(QuoteRequest{RequestID: "q-new", ItemID: "seat", VersionID: "seat-v2", Quantity: 1})
519		if !out.Confirmed {
520			t.Fatalf("新版在交接点应可报价: %+v", out)
521		}
522	}
523	
524	// 查询是只读操作：不受理报价、不占用请求标识，也不产生可被 Lookup 的记录。
525	func TestEffectiveVersionAtDoesNotConsumeRequestID(t *testing.T) {
526		b, _ := newEffectiveVersionBook(t, effV1Start)
527	
528		// 大量查询前后，未使用过的标识都查不到报价记录。
529		for i := 0; i < 8; i++ {
530			if _, err := b.EffectiveVersionAt("seat", effV1Start.Add(time.Duration(i)*24*time.Hour)); err != nil {
531				t.Fatalf("查询 %d 意外失败: %v", i, err)
532			}
533		}
534		if _, err := b.Lookup("quote-after-queries"); !errors.Is(err, ErrRequestNotFound) {
535			t.Fatalf("只读查询不应产生报价记录: %v", err)
536		}
537	
538		// 该标识仍是全新的：首次报价正常受理并被保存。
539		out, err := b.Quote(QuoteRequest{
540			RequestID: "quote-after-queries", ItemID: "seat", VersionID: "seat-v1", Quantity: 2,
541		})
542		if err != nil || !out.Confirmed || out.Total != 300 {
543			t.Fatalf("查询不应占用请求标识或影响首次受理: %+v (%v)", out, err)
544		}
545		got, err := b.Lookup("quote-after-queries")
546		if err != nil || got != out {
547			t.Fatalf("首次受理结果应原样可查: %+v (%v)", got, err)
548		}
549	
550		// 查询“无生效版本”的时刻同样不留任何报价痕迹。
551		if _, err := b.EffectiveVersionAt("seat", effV2End); !errors.Is(err, ErrNoEffectiveVersion) {
552			t.Fatalf("前提：3 月 20 日应无生效版本, got %v", err)
553		}
554		views, err := b.ItemVersions("seat")
555		if err != nil || len(views) != 2 {
556			t.Fatalf("查询不应改动版本集合: %d 个版本 (%v)", len(views), err)
557		}
558	}
559	
560	// 并发只读查询应始终给出一致结论。
561	func TestEffectiveVersionAtConcurrentReads(t *testing.T) {
562		b, _ := newEffectiveVersionBook(t, effV1Start)
563	
564		const n = 32
565		var wg sync.WaitGroup
566		errs := make(chan error, n)
567		for i := 0; i < n; i++ {
568			wg.Add(1)
569			go func(i int) {
570				defer wg.Done()
571				got, err := b.EffectiveVersionAt("seat", effV2Start)
572				if err != nil {
573					errs <- fmt.Errorf("查询 %d: %w", i, err)
574					return
575				}
576				if got.VersionID != "seat-v2" || got.UnitPrice != 180 {
577					errs <- fmt.Errorf("查询 %d 结果异常: %+v", i, got)
578				}
579			}(i)
580		}
581		wg.Wait()
582		close(errs)
583		for err := range errs {
584			t.Error(err)
585		}
586	}
