	//    此时没有任何生效版本，旧版不会因为新版到期而重新生效。
	if _, err := b.EffectiveVersionAt("seat", qqFutureQuery); !errors.Is(err, ErrNoEffectiveVersion) {
		t.Fatalf("3 月 20 日零点应返回 ErrNoEffectiveVersion, got %v", err)
	}

